calc(36,r'g(x)=\begin{cases}4-2x&0\le x\le2\\-\sqrt{4-(x-4)^2}&2\le x\le6\\x-6&6\le x\le7\end{cases}','직선 둘과 아래쪽 반원으로 된 그래프에서 (a) 영부터 이 (b) 이부터 육 (c) 영부터 칠의 적분을 넓이로 구하라.','For the two line segments and lower semicircle, evaluate integrals (a) zero to two, (b) two to six, and (c) zero to seven using areas.',[r'\int_0^2g=(2)(4)/2=4',r'\int_2^6g=-\pi(2)^2/2=-2\pi',r'\int_6^7g=(1)(1)/2=1/2'],r'\text{(a)}\ 4;\quad\text{(b)}\ -2\pi;\quad\text{(c)}\ 9/2-2\pi',sub='abc');rectplot(36,lambda z:4-2*z if z<=2 else-math.sqrt(max(0,4-(z-4)**2))if z<=6 else z-6,0,7,[(420,'signed area')])
geom=[(41,10-5*x,-2,5,r'A_+=(4)(20)/2=40,\quad A_-=(3)(15)/2=45/2',S.Rational(35,2)),(42,2*x-1,-1,3,r'A_+=(5/2)(5)/2=25/4,\quad A_-=(3/2)(3)/2=9/4',S.Integer(4)),(43,S.Abs(x)/2,-4,3,r'I=(4)(2)/2+(3)(3/2)/2',S.Rational(25,4)),(44,S.Abs(2*x-1),0,1,r'I=2\cdot(1/2)(1)/2',S.Rational(1,2)),(45,1+S.sqrt(9-x*x),-3,0,r'I=\text{rectangle }3\cdot1+\text{quarter disk }\pi3^2/4',3+9*S.pi/4),(46,2*x-S.sqrt(16-x*x),-4,4,r'\int_{-4}^4 2x\,dx=0,\quad\int_{-4}^4\sqrt{16-x^2}\,dx=\pi4^2/2',-8*S.pi)]
