for q,eq,lines,ans in[(53,r'\int_0^1(5-6x^2)\,dx',[r'5\int_0^1 1\,dx-6\int_0^1x^2\,dx=5-6(1/3)'],r'3'),(54,r'\int_2^5(1+3x^4)\,dx',[r'\int_2^5 1\,dx+3\int_2^5x^4\,dx=3+3(5^5-2^5)/5'],r'9294/5'),(55,r'\int_1^4(2x^2-3x+1)\,dx',[r'2(4^3-1^3)/3-3(4^2-1^2)/2+(4-1)'],r'45/2'),(56,r'\int_0^{\pi/2}(2\cos x-5x)\,dx',[r'2\int_0^{\pi/2}\cos x\,dx-5\int_0^{\pi/2}x\,dx=2-5(\pi/2)^2/2'],r'2-5\pi^2/8')]:calc(q,eq,'앞의 적분값과 선형성으로 계산하라.','Use earlier integral values and linearity to evaluate.',lines,ans)
