calc(58,r'\int_2^8f(x)\,dx=7.3,\quad\int_2^4f(x)\,dx=5.9','사부터 팔의 적분을 구하라.','Find the integral from four to eight.',[r'\int_4^8f=\int_2^8f-\int_2^4f=7.3-5.9'],r'1.4')
