for q,eq,lines,ans in[(67,r'I=\int_{-1}^1\sqrt{1+x^2}\,dx',[r'1\le\sqrt{1+x^2}\le\sqrt2\quad(-1\le x\le1)',r'b-a=2'],r'2\le I\le2\sqrt2'),(68,r'I=\int_{\pi/6}^{\pi/3}\sin x\,dx',[r'1/2\le\sin x\le\sqrt3/2',r'b-a=\pi/6'],r'\pi/12\le I\le\sqrt3\pi/12'),(69,r'I=\int_0^1x^3\,dx',[r'0\le x^3\le1,\quad b-a=1'],r'0\le I\le1'),(70,r'I=\int_0^3\frac{dx}{x+4}',[r'1/7\le1/(x+4)\le1/4,\quad b-a=3'],r'3/7\le I\le3/4'),(71,r'I=\int_{\pi/4}^{\pi/3}\tan x\,dx',[r'1\le\tan x\le\sqrt3,\quad b-a=\pi/12'],r'\pi/12\le I\le\sqrt3\pi/12'),(72,r'I=\int_0^2(x^3-3x+3)\,dx',[r'f^{\prime}(x)=3(x^2-1)',r'f(0)=3,\quad f(1)=1,\quad f(2)=5',r'1\le f(x)\le5,\quad b-a=2'],r'2\le I\le10'),(73,r'I=\int_{-1}^1\sqrt{1+x^4}\,dx',[r'0\le x^4\le1\Rightarrow1\le\sqrt{1+x^4}\le\sqrt2',r'b-a=2'],r'2\le I\le2\sqrt2'),(74,r'I=\int_\pi^{2\pi}(x-2\sin x)\,dx',[r'f^{\prime}(x)=1-2\cos x=0\Rightarrow x=5\pi/3',r'f(\pi)=\pi,\quad f(2\pi)=2\pi,\quad f(5\pi/3)=5\pi/3+\sqrt3',r'\min f=\pi,\quad\max f=5\pi/3+\sqrt3,\quad b-a=\pi'],r'\pi^2\le I\le5\pi^2/3+\sqrt3\pi')]:calc(q,eq,'함숫값의 상하한과 구간 길이로 적분을 추정하라.','Estimate the integral using function bounds and interval length.',lines+[r'm(b-a)\le I\le M(b-a)'],ans)
calc(75,r'\int_1^3\sqrt{x^4+1}\,dx\ge26/3','함수 비교로 부등식을 증명하라.','Prove the inequality by comparison.',[r'\sqrt{x^4+1}\ge\sqrt{x^4}=x^2',r'\int_1^3\sqrt{x^4+1}\,dx\ge\int_1^3x^2\,dx=(27-1)/3'],r'\int_1^3\sqrt{x^4+1}\,dx\ge26/3')
calc(76,r'\int_0^{\pi/2}x\sin x\,dx\le\pi^2/8','함수 비교로 부등식을 증명하라.','Prove the inequality by comparison.',[r'0\le\sin x\le1,\quad x\ge0\Rightarrow x\sin x\le x',r'\int_0^{\pi/2}x\sin x\,dx\le\int_0^{\pi/2}x\,dx=(\pi/2)^2/2'],r'\int_0^{\pi/2}x\sin x\,dx\le\pi^2/8')
calc(77,r'A=\int_1^2\sqrt x\,dx,\quad B=\int_1^2\sqrt{1/x}\,dx,\quad C=\int_1^2\sqrt[4]x\,dx','계산 없이 가장 큰 적분을 고르라.','Choose the largest integral without evaluating.',[r'1<x\le2:\quad x^{1/2}>x^{1/4}>x^{-1/2}',r'A>C>B'],r'A=\int_1^2\sqrt x\,dx\text{ is largest}')
calc(78,r'A=\int_0^{1/2}\cos(x^2)\,dx,\quad B=\int_0^{1/2}\cos\sqrt x\,dx','계산 없이 두 적분을 비교하라.','Compare the integrals without evaluating.',[r'0<x\le1/2:\quad x^2<\sqrt x<\pi',r'\cos\text{ is strictly decreasing on }[0,\pi]',r'\cos(x^2)>\cos\sqrt x'],r'A>B')
calc(79,r'\int_a^b cf(x)\,dx=c\int_a^b f(x)\,dx','적분 가능한 함수와 실수 상수에 대해 상수배 성질을 리만합으로 증명하라.','Prove the scalar-multiple property from Riemann sums for an integrable function and a real constant.',[r'\sum_i cf(x_i^*)\Delta x_i=c\sum_i f(x_i^*)\Delta x_i',r'\lim_{\|P\|\to0}c\sum_i f(x_i^*)\Delta x_i=c\int_a^b f(x)\,dx',r'a=b:\ 0=c\cdot0;\quad a>b:\ \text{reverse limits}'],r'\int_a^b cf=c\int_a^b f','상수가 음수이거나 영이어도 유한합의 항등식과 극한의 상수배 법칙은 그대로 성립한다.','The finite-sum identity and constant-multiple limit law hold for negative and zero constants as well.')
calc(80,r'f\text{ is continuous on }[a,b],\quad a<b;\quad \left|\int_a^b f\right|\le\int_a^b|f|;\quad\left|\int_a^b f(x)\sin(2x)\,dx\right|\le\int_a^b|f|','(a) 양·음의 부분이 있는 그래프의 넓이로 절댓값 부등식을 설명하고 (b) 일반적으로 증명하며 (c) 사인 인자를 넣은 부등식을 증명하라.','(a) Explain the absolute-value inequality using positive and negative graph areas, (b) prove it in general, and (c) prove its version with a sine factor.',[r'\text{(a)}\ P=\text{positive area},\quad N=\text{negative unsigned area}',r'\left|\int_a^b f\right|=|P-N|\le P+N=\int_a^b|f|',r'\text{(b)}\ -|f(x)|\le f(x)\le|f(x)|',r'-\int_a^b|f|\le\int_a^b f\le\int_a^b|f|',r'\text{(c)}\ \left|\int_a^b f(x)\sin(2x)\,dx\right|\le\int_a^b|f(x)\sin(2x)|\,dx\le\int_a^b|f(x)|\,dx'],r'\left|\int_a^b f\right|\le\int_a^b|f|;\quad\left|\int_a^b f(x)\sin(2x)\,dx\right|\le\int_a^b|f|',sub='abc')
rectplot(80,lambda z:-math.sin(z),-math.pi,2*math.pi,[(450,'signed area')],caption=bi('부호 있는 넓이 설명을 위한 자체 예시. 파란 넓이의 합을 양의 넓이, 주황 넓이의 합을 음의 부분의 절댓값으로 두면 같은 증명이 임의의 그래프에 적용된다.','Original illustrative example: let the total blue area be the positive area and the total orange area the unsigned negative area. The same argument applies to any graph.'))
calc(81,r'f(x)=\begin{cases}0&x\in\mathbb Q\\1&x\notin\mathbb Q\end{cases},\quad0\le x\le1','리만합으로 이 함수가 적분 가능하지 않음을 증명하라.','Use Riemann sums to prove that this function is not integrable.',[r'\text{Every nonempty interval contains rational and irrational points}',r'\text{All rational tags: }\sum_i f(x_i^*)\Delta x_i=0',r'\text{All irrational tags: }\sum_i f(x_i^*)\Delta x_i=\sum_i\Delta x_i=1',r'\|P\|\to0:\quad0\ne1'],r'f\text{ is not Riemann integrable on }[0,1]','분할의 망을 아무리 작게 해도 표본점 선택에 따라 서로 다른 두 극한이 생긴다.','Arbitrarily fine partitions give two different limits depending on the tags.')
calc(82,r'f(x)=\begin{cases}0&x=0\\1/x&0<x\le1\end{cases}','첫 구간의 표본점을 영에 매우 가깝게 골라 리만 적분이 존재하지 않음을 보여라.','Choose the first tag very close to zero to show that no Riemann integral exists.',[r'\Delta x=1/n,\quad x_1^*=1/n^3\in(0,1/n)\quad(n\ge2)',r'f(x_1^*)\Delta x=n^3/n=n^2',r'\sum_{i=1}^n f(x_i^*)\Delta x\ge n^2\to\infty'],r'f\text{ is not Riemann integrable on }[0,1]','나머지 표본점은 각 구간 안에서 아무렇게나 골라도 모든 항이 음수가 아니므로 하한이 유지된다.','Every remaining tag contributes a nonnegative term, so this lower bound holds regardless of their choice.')
calc(83,r'\lim_{n\to\infty}\frac{1^4+2^4+\cdots+n^4}{n^5}','주어진 극한을 정적분으로 나타내라.','Express the limit as a definite integral.',[r'\frac1{n^5}\sum_{i=1}^n i^4=\sum_{i=1}^n(i/n)^4(1/n)',r'\Delta x=1/n,\quad x_i=i/n,\quad0\le x\le1'],r'\int_0^1x^4\,dx')
calc(84,r'\lim_{n\to\infty}\frac1n\left[\frac1{1+(1/n)^2}+\frac1{1+(2/n)^2}+\cdots+\frac1{1+(n/n)^2}\right]','주어진 극한을 정적분으로 나타내라.','Express the limit as a definite integral.',[r'\Delta x=1/n,\quad x_i=i/n,\quad f(x)=1/(1+x^2)',r'\lim_{n\to\infty}\sum_{i=1}^n f(x_i)\Delta x=\int_0^1 f(x)\,dx'],r'\int_0^1\frac{dx}{1+x^2}')
calc(85,r'I=\int_1^2\frac{dx}{x^2},\quad x_i=1+i/n,\quad x_i^*=\sqrt{x_{i-1}x_i}','각 부분구간 끝점의 기하평균을 표본점으로 사용하여 정의에서 적분값을 계산하라.','Evaluate from the definition using the geometric mean of each pair of subinterval endpoints as the tag.',[r'x_{i-1}\le\sqrt{x_{i-1}x_i}\le x_i\quad(x_{i-1}>0)',r'\frac{\Delta x}{(x_i^*)^2}=\frac{n}{(n+i-1)(n+i)}=n\left(\frac1{n+i-1}-\frac1{n+i}\right)',r'\sum_{i=1}^n\frac{\Delta x}{(x_i^*)^2}=n\left(\frac1n-\frac1{2n}\right)=\frac12',r'\Delta x\to0:\quad I=\lim_{n\to\infty}\frac12=\frac12'],r'1/2')
for ex in items:
 q=ex['number']
 if 65<=q<=78:ex['hint']=bi('적분함수의 점별 대소 관계를 먼저 구한 뒤 적분의 비교 성질을 적용한다.','First compare the integrands pointwise, then apply the integral comparison property.')
